// Candle duel question bank — seed data (docs/05 §2, ADR 0005 §15).
// Content only — no logic lives here.
import type { Prisma } from '@prisma/client';
import {
  generateChart,
  type ChartData,
  type ChartTemplateKey,
} from '../src/modules/question-bank/chart-generator';
// Rules enforced by convention: every item is ORIGINAL, written for
// Candle in simple English. No copied Varsity text, no real companies,
// no real tickers, no investment advice. Fictional companies are named
// as fictional where they appear. Every item has a 1–3 sentence
// explanation. Items seed as LIVE (they were authored + reviewed as
// part of this file); template-generated variants seed as DRAFT and go
// through review like any item.
//
// Coverage: 620 LIVE items — 10 topics x 52 (qb-001..qb-520) + 50 CASE_CHOICE
// (qb-521..qb-570, 5 per topic) + 50 CHART_CHOICE (qb-571..qb-620, 5 per
// topic). Per topic for qb-001..qb-520: difficulties
// money-basics 9/13/12/9/9, budgeting 9/13/12/9/9, banking-saving
// 10/12/12/9/9, stocks 9/13/12/9/9, mutual-funds 10/12/12/9/9, risk
// 9/13/12/9/9, compounding 8/14/12/9/9, tax-basics 8/13/12/9/10,
// insurance 9/13/12/9/9, markets 9/13/12/9/9 (bank totals
// 90/129/120/90/91); 461 MCQ_4 + 59 TRUE_FALSE + 50 CASE_CHOICE.
// CASE_CHOICE difficulties are 2:15 / 3:20 / 4:15, skills JUDGEMENT 20 /
// SCENARIO 20 / RISK_ASSESSMENT 10. CHART_CHOICE difficulties are also
// 2:15 / 3:20 / 4:15, skill CHART_READING 50. Bank totals with charts:
// 90/159/160/120/91; 461 MCQ_4 + 59 TRUE_FALSE + 50 CASE_CHOICE +
// 50 CHART_CHOICE. Skills: recall / calculation / judgement / scenario /
// risk-assessment / chart-reading across the bank.
//
// Provenance (Phase 4 growth, 2026-11-11): qb-001..qb-120 are the Phase 3
// items, untouched. qb-121..qb-520 add 400 items — 131 materialised
// template variants (enumerated from template-engine.ts and verified
// against the TS engine: 5 tpl-budgeting-503020, 24 tpl-emergency-fund,
// 30 tpl-sip-goal, 20 tpl-compounding, 20 tpl-simple-vs-compound,
// 32 tpl-tax-slab) and 269 hand-written original items. The seed items
// were authored by the Phase 4 Stage 1 builder and reviewed by the
// Phase 4 coordinator before seeding as LIVE; the 6 templates
// themselves seed as DRAFT, and variants generated at runtime through
// POST /templates/:id/generate still seed as DRAFT and go through the
// CMS workflow like any item. Template difficulties in the seed are
// author estimates by parameter size (e.g. longer SIP horizons and
// higher tax rates are harder); pilot + calibration set the real
// difficulty later (docs/05 §2.5).
//
// Provenance (Phase 8 Stage 1 growth, 2026-11-12): qb-571..qb-620 add 50
// CHART_CHOICE items (5 per topic), authored by the Phase 8 Stage 1 builder
// and reviewed by the coordinator before seeding as LIVE (two-person rule,
// docs/05 §2.2). Difficulties 2:15 / 3:20 / 4:15 (no 1 or 5 — charts are
// read, not recalled); skill CHART_READING only. Every CHART_CHOICE item
// has a one-line stem, a chart generated by the seeded chart generator
// (chart-generator.ts: same key + template + fictional instrument always
// replays the same 6-point series), 4 interpretations with exactly 1
// correct, and a 1–3 sentence explanation showing how to read the chart.
// The CHART_CHOICE format (renderer + generator + bank) is Stage 1; the
// Chart Detective duel itself is Stage 2.

export type DuelBankSeedSkill =
  'RECALL' | 'CALCULATION' | 'JUDGEMENT' | 'CHART_READING' | 'SCENARIO' | 'RISK_ASSESSMENT';
export type DuelBankSeedType = 'MCQ_4' | 'TRUE_FALSE' | 'CASE_CHOICE' | 'CHART_CHOICE';

export interface DuelBankSeedOption {
  text: string;
  isCorrect: boolean;
  /** CASE_CHOICE only: per-option score fraction (100 / 50 / 0). */
  points?: number;
  /** CASE_CHOICE only: one-line consequence shown under the action card. */
  consequence?: string;
}

export interface DuelBankSeedItem {
  key: string;
  topic: string;
  skill: DuelBankSeedSkill;
  type: DuelBankSeedType;
  difficulty: 1 | 2 | 3 | 4 | 5;
  stem: string;
  explanation: string;
  options: DuelBankSeedOption[];
  /** CASE_CHOICE only: labelled case numbers, e.g. {"Monthly income": "₹45,000"}. */
  context?: Record<string, string | number>;
  /** CASE_CHOICE only: why the best action wins, line by line. */
  rubric?: string;
  /** CHART_CHOICE only: structured chart data (from the seeded generator). */
  chart?: ChartData;
}

export interface DuelBankSeedTemplate {
  key: string;
  topic: string;
  skill: 'CALCULATION';
  templateText: string;
  parameterSchema: Prisma.InputJsonValue;
  answerFormula: string;
  distractorRules: Prisma.InputJsonValue;
}

function mcq(
  key: string,
  topic: string,
  skill: DuelBankSeedSkill,
  difficulty: 1 | 2 | 3 | 4 | 5,
  stem: string,
  explanation: string,
  correct: string,
  w1: string,
  w2: string,
  w3: string
): DuelBankSeedItem {
  // Vary the correct option's position by key number so it is not
  // always in the same slot.
  const pos = Number(key.slice(3)) % 4;
  const wrongs = [w1, w2, w3];
  const options: DuelBankSeedOption[] = [];
  let wi = 0;
  for (let i = 0; i < 4; i++) {
    if (i === pos) options.push({ text: correct, isCorrect: true });
    else options.push({ text: wrongs[wi++] as string, isCorrect: false });
  }
  return { key, topic, skill, type: 'MCQ_4', difficulty, stem, explanation, options };
}

function tf(
  key: string,
  topic: string,
  skill: DuelBankSeedSkill,
  difficulty: 1 | 2 | 3 | 4 | 5,
  stem: string,
  explanation: string,
  isTrue: boolean
): DuelBankSeedItem {
  return {
    key,
    topic,
    skill,
    type: 'TRUE_FALSE',
    difficulty,
    stem,
    explanation,
    options: [
      { text: 'True', isCorrect: isTrue },
      { text: 'False', isCorrect: !isTrue },
    ],
  };
}

interface CaseAction {
  text: string;
  consequence: string;
}

/**
 * CASE_CHOICE builder (Phase 7 Stage 1, docs/08 §3.3). `best` is the
 * defensible best action (100 points), `second` is the plausibly
 * tempting second-best (50 points), `others` are weak/harmful (0).
 * The option order is rotated by key number so the best action is not
 * always in the same slot. Stem is 3–5 short lines joined with '\n';
 * context carries at least 2 labelled entries with numbers; rubric
 * has one line per judgement (best / second-best / weak).
 */
function caseChoice(
  key: string,
  topic: string,
  skill: DuelBankSeedSkill,
  difficulty: 1 | 2 | 3 | 4 | 5,
  stem: string,
  explanation: string,
  context: Record<string, string | number>,
  rubric: string,
  best: CaseAction,
  second: CaseAction,
  ...others: CaseAction[]
): DuelBankSeedItem {
  const ordered: DuelBankSeedOption[] = [
    { text: best.text, isCorrect: true, points: 100, consequence: best.consequence },
    { text: second.text, isCorrect: false, points: 50, consequence: second.consequence },
    ...others.map((o) => ({
      text: o.text,
      isCorrect: false,
      points: 0,
      consequence: o.consequence,
    })),
  ];
  const pos = Number(key.slice(3)) % ordered.length;
  const options = [...ordered.slice(pos), ...ordered.slice(0, pos)];
  return {
    key,
    topic,
    skill,
    type: 'CASE_CHOICE',
    difficulty,
    stem,
    explanation,
    context,
    rubric,
    options,
  };
}

/**
 * CHART_CHOICE builder (Phase 8 Stage 1, docs/08 §3.4). `correct` is the
 * one true interpretation of the chart; the three distractors are
 * readings the chart does NOT support. The chart itself is generated
 * from the item key + template + fictional instrument, so the same key
 * always replays the same 6-point series. The option order is rotated
 * by key number so the correct reading is not always in the same slot.
 * Stem is one line (the question); explanation is 1–3 sentences
 * showing how to read the chart.
 */
function chartChoice(
  key: string,
  topic: string,
  difficulty: 1 | 2 | 3 | 4 | 5,
  stem: string,
  explanation: string,
  template: ChartTemplateKey,
  instrument: string,
  correct: string,
  ...distractors: string[]
): DuelBankSeedItem {
  const chart = generateChart(key, template, instrument);
  const ordered: DuelBankSeedOption[] = [
    { text: correct, isCorrect: true },
    ...distractors.map((t) => ({ text: t, isCorrect: false })),
  ];
  const pos = Number(key.slice(3)) % ordered.length;
  const options = [...ordered.slice(pos), ...ordered.slice(0, pos)];
  return {
    key,
    topic,
    skill: 'CHART_READING',
    type: 'CHART_CHOICE',
    difficulty,
    stem,
    explanation,
    chart,
    options,
  };
}

